.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);   /* icon↔label */
  height: var(--control-height);
  padding-inline: var(--control-padding-x);
  border-radius: var(--control-radius);
  font-weight: var(--control-font-weight);
  font-size: var(--control-font-size);
  background: var(--primary);
  color: var(--primary-foreground);
  transition: background var(--duration-fast);
  /* A label wraps onto two lines only when someone asks for it. A button that folds "Run again"
   * into a two-line pill reads as broken, and it happens whenever a flex parent squeezes it. */
  white-space: nowrap;
}
/* Icons in buttons always trail the label (`order` works with the flex row,
 * so it mirrors in RTL). The `iconEnd` prop it replaced was deleted 2026-09-03: it did nothing, and an
 * inert prop in the registry is a prop an agent tries. */
.btn > .icon {
  order: 1;
}

/* [data-open] = the button is acting as an open dropdown trigger; mirror hover. */
.btn:hover,
.btn[data-open] { background: var(--primary-hover); }
/* PRESSED. The system had hover and then nothing: a click on a slow action
 * gave no answer at all, which is why people press twice. One more stop in the
 * same direction the hover already moved. */
.btn:active { background: var(--primary-active); }
.btn:disabled {
  opacity: var(--disabled-opacity);
  cursor: not-allowed;
  pointer-events: none;
}
/* Loading: the button stays full opacity (it is working, not disabled), the
 * spinner leads, and any icon is hidden so it does not sit next to the spinner. */
.btn[data-loading] {
  opacity: 1;
  cursor: progress;
}
.btn[data-loading] > .icon {
  display: none;
}
.btn-spinner {
  order: -1; /* lead the label regardless of the icon's trailing order */
}

.btn[data-size="sm"] {
  height: var(--control-height-sm);
  padding-inline: var(--space-3);
  font-size: var(--font-sm);
}
.btn[data-size="lg"] {
  height: var(--control-height-lg);
  font-size: var(--control-font-size-lg);   /* type scales modestly with size */
}
.btn[data-block="true"] { width: 100%; }

/* No line round a button (owner, 2026-08-22). It used to carry an inset hairline, and the reason
 * was real: `--secondary` and `--muted` are both neutral-100 in light and both neutral-8xx in
 * dark, so a secondary button standing on a PAGE was the exact colour of what was behind it —
 * page-header actions read as plain text with no edges. The line was the wrong answer to a real
 * question. The right one is the same one the filled icon button and the pill now give: ask the
 * surface. --surface-contrast is white on the grey page and grey on a white card, so the button
 * separates by its FILL on either, and hover moves one stop further from the surface. */
/* Still no line round a button — asked for on 2026-08-22, and again on 08-23
 * when one was tried. A boundary drawn at 3:1 is a mid-grey hairline, and on a
 * quiet action that reads as chrome the design does not want. What the button
 * separates by is its FILL, and the fill now asks the surface, which is the
 * part that was actually broken: inside a Modal or a SidePanel this measured
 * 1.00:1 — the exact colour of what it stood on — and it now measures 1.15
 * light / 1.33-1.49 dark, the same separation a card already gives it.
 *
 * That is below the 3:1 SC 1.4.11 asks of a component boundary, and it is a
 * deliberate, recorded decision rather than an oversight: the label carries
 * 4.5:1 and the shape is a filled pill. `npm run boundary` measures edge tokens
 * and does not hold button fills to the floor, so this is not a check quietly
 * switched off — it was never in scope. */
.btn[data-variant="secondary"] {
  background: var(--surface-contrast);
  color: var(--secondary-foreground);
  /* Unset on every surface but a tone tint, where a fill cannot separate at all.
   * See --surface-contrast-shadow in styles/utilities.css. */
  box-shadow: var(--surface-contrast-shadow, none);
}
.btn[data-variant="secondary"]:hover,
.btn[data-variant="secondary"][data-open] { background: var(--surface-contrast-hover); }
.btn[data-variant="secondary"]:active { background: var(--surface-contrast-active); }

.btn[data-variant="ghost"] {
  background: transparent;
  color: var(--foreground);
}
.btn[data-variant="ghost"]:hover,
.btn[data-variant="ghost"][data-open] { background: var(--accent-soft); }
.btn[data-variant="ghost"]:active { background: var(--accent); }

.btn[data-variant="destructive"] {
  background: var(--destructive);
  color: var(--destructive-foreground);
}
.btn[data-variant="destructive"]:hover,
.btn[data-variant="destructive"][data-open] { background: color-mix(in oklch, var(--destructive) 88%, black); }
.btn[data-variant="destructive"]:active { background: color-mix(in oklch, var(--destructive) 76%, black); }

/* Success: a prominent green action. Used where a state change demands an
 * obvious "apply" (e.g. regenerate a stale report), not for routine confirms. */
.btn[data-variant="success"] {
  background: var(--success);
  color: var(--success-foreground);
}
.btn[data-variant="success"]:hover,
.btn[data-variant="success"][data-open] { background: color-mix(in oklch, var(--success) 88%, black); }
.btn[data-variant="success"]:active { background: color-mix(in oklch, var(--success) 76%, black); }

/* Dark — solid neutral-dark fill (neutral-820), white text. */
.btn[data-variant="dark"] {
  background: var(--secondary-foreground);
  color: var(--background);
}
.btn[data-variant="dark"]:hover,
.btn[data-variant="dark"][data-open] { background: var(--foreground); }
.btn[data-variant="dark"]:active { background: color-mix(in oklch, var(--foreground) 82%, white); }

/* AI — the assistant's own action (open the assistant, generate, rewrite).
 * Violet rather than brand, so "the machine did this" never reads as a normal
 * product action. */
.btn[data-variant="ai"] {
  background: var(--ai);
  color: var(--ai-foreground);
}
.btn[data-variant="ai"]:hover,
.btn[data-variant="ai"][data-open] { background: color-mix(in oklch, var(--ai) 88%, black); }
.btn[data-variant="ai"]:active { background: color-mix(in oklch, var(--ai) 76%, black); }

/* Link — brand-coloured inline text action, no button chrome. Resets the
 * control height/padding so it reads as a link, not a pill. */
.btn[data-variant="link"] {
  height: auto;
  padding-inline: 0;
  background: transparent;
  /* Same token <Link> uses. This one is still a <button> — an action that looks
   * like a link — and it has to be the same colour as a real link or the two
   * read as different things while doing the same thing to the eye. */
  color: var(--link);
}
.btn[data-variant="link"]:hover,
.btn[data-variant="link"][data-open] {
  background: transparent;
  color: var(--link-hover);
  text-decoration: underline;
}
.btn[data-variant="link"]:active { background: transparent; color: var(--primary-active); }

import './Button.css'
import { type ButtonHTMLAttributes, type ReactNode, type Ref } from 'react'
import { cn } from '../lib/cn'
import { Spinner } from '../Spinner'

type Variant = 'primary' | 'secondary' | 'ghost' | 'destructive' | 'success' | 'dark' | 'link' | 'ai'
type Size = 'sm' | 'md' | 'lg'

type Props = ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Forwarded to the underlying <button>. */
  ref?: Ref<HTMLButtonElement>
  /** How much weight this action carries ON THE SCREEN — which makes it a
   *  decision about the screen, not about the button. Exactly one action is
   *  `primary`: the thing the reader came to do. Everything beside it is
   *  `secondary`, which is also what a button with no variant gets, and that is
   *  the right default for a control nobody has thought about yet. `ghost` is
   *  for a control that must not compete with the content under it.
   *  `destructive` is reserved for what cannot be undone, where the colour IS
   *  the warning — and it does not remove the need to confirm. */
  variant?: Variant
  /** Control height: sm 32 / md 40 (default) / lg 52. State it whenever the
   *  button sits beside an `<IconButton>`, which defaults to `sm`. */
  size?: Size
  /** Fills the width it is given. For a button that is the whole of a narrow
   *  column — a form's submit on a phone, a card's single action — never as a
   *  way to make one button look important in a row. */
  block?: boolean
  /** In-flight action: shows a spinner in place of the icon and blocks further
   *  clicks. The label stays so the button keeps its width. Set the accessible
   *  busy text with `loadingLabel`. */
  loading?: boolean
  /** What the spinner announces while `loading` (default "Loading"). */
  loadingLabel?: string
  children?: ReactNode
}

/**
 * The action control: `variant` sets its weight, `loading` swaps the icon for
 * a spinner and disables it while it runs.
 *
 * Copy: the verb the reader is about to perform, with its object when the screen
 * has more than one — "Send invoice", not "Submit", never "OK". The label
 * is a promise about what happens next.
 */
export function Button({
  variant, size, block, loading, loadingLabel = 'Loading', disabled, className, ref, children, ...rest
}: Props) {
  return (
    <button
      ref={ref}
      className={cn('btn', className)}
      data-variant={variant}
      data-size={size}
      data-block={block || undefined}
      data-loading={loading || undefined}
      disabled={disabled || loading || undefined}
      aria-busy={loading || undefined}
      {...rest}
    >
      {loading && <Spinner size="sm" label={loadingLabel} className="btn-spinner" />}
      {children}
    </button>
  )
}
